def apply(inputs,premises):
    o=inputs.get('observation')
    if not isinstance(o,dict):
        return {'bindings':[],'unresolved':['factual observation required']}
    year=o['query_year']
    close=str(year)+'-12-31'
    b={'query_person':o['query_person'],'query_year':year}
    u=list(o['unresolved'])
    if o['marriage_resolution']=='resolved':
        rows=[]
        for r in o['marriage_evidence']:
            kind=r['evidence_type']
            end=None
            opened=False
            if kind=='ongoing_through_close':
                end=close
            elif kind=='closed_interval':
                end=r['end_date']
            rows.append({'individual':r['individual'],'spouse':r['spouse'],'start_date':r['start_date'],'end_date':end,'open_ended':opened})
        b['marriage_intervals']=rows
    else:
        u.append('marriage evidence was not resolved')
    if o['decree_resolution']=='resolved':
        rows=[]
        for r in o['decree_evidence']:
            kind=r['evidence_type']
            end=None
            opened=False
            if kind=='effective_through_close':
                end=close
            elif kind=='closed_interval':
                end=r['end_date']
            rows.append({'individual':r['individual'],'spouse':r['spouse'],'decree_type':r['decree_type'],'effective_date':r['effective_date'],'end_date':end,'open_ended':opened})
        b['legal_separation_decrees']=rows
    else:
        u.append('legal-separation decree evidence was not resolved')
    if o['return_resolution']=='resolved':
        b['return_records']=list(o['return_records'])
    else:
        u.append('return facts were not resolved')
    if o['itemization_resolution']=='resolved':
        b['itemization_records']=list(o['itemization_records'])
    else:
        u.append('itemized-deduction events were not resolved')
    return {'bindings':[{'inputs':b,'witnesses':list(o['witnesses'])}],'unresolved':u}

